    if ((fl_flags & (1u << 2)) != 0) { out.privacy = tl::read_vector<std::shared_ptr<tl::PrivacyRule>>(rv, [&](TlReader& r882) -> std::shared_ptr<tl::PrivacyRule> { return tl::read_boxed<tl::PrivacyRule>(r882); }); }
    if ((fl_flags & (1u << 3)) != 0) { out.views = tl::read_boxed<tl::StoryViews>(rv); }
